DAY_BONUS = 5


def record_what_was_paid(apps, schema_editor):
    """Until now every member was paid for every stop the organiser completed.
    Record those payments as check-ins, day bonuses and completion XP, so undo
    still takes back exactly what was paid and past achievements still count."""
    Activity = apps.get_model("trips", "Activity")
    DayBonus = apps.get_model("trips", "DayBonus")
    StopCheckIn = apps.get_model("trips", "StopCheckIn")
    TripMember = apps.get_model("trips", "TripMember")

    done = Activity.objects.filter(status="completed", day__trip__is_past=False).select_related("day__trip")
    for activity in done.iterator():
        trip = activity.day.trip
        for member in TripMember.objects.filter(trip=trip):
            # Only people already on the trip when it was completed were paid for it.
            if activity.completed_at and member.joined_at > activity.completed_at:
                continue
            StopCheckIn.objects.get_or_create(
                activity=activity,
                user_id=member.user_id,
                defaults={
                    "distance_m": activity.completed_distance_m,
                    "xp_paid": 0 if trip.no_xp else activity.xp_value,
                },
            )

    Day = apps.get_model("trips", "Day")
    for day in Day.objects.filter(trip__is_past=False, trip__no_xp=False).select_related("trip"):
        stops = list(day.activities.all())
        if not stops or any(s.status != "completed" for s in stops):
            continue
        last = max((s.completed_at for s in stops if s.completed_at), default=None)
        for member in TripMember.objects.filter(trip=day.trip):
            if last and member.joined_at > last:
                continue
            DayBonus.objects.get_or_create(day=day, user_id=member.user_id, defaults={"amount": DAY_BONUS})

    for member in TripMember.objects.filter(trip__status="completed", trip__is_past=False, trip__no_xp=False).select_related("trip"):
        member.completion_xp = member.trip.completion_bonus
        member.save(update_fields=["completion_xp"])


